/* The engine library's loader, in the host executable (build_boot.py
 * --engine-library; pc/docs/plans/2026-10-19-engine-reload.md).
 *
 * The host is the game and its state; the engine (librood_engine.so, the
 * rest of pc/) is loaded here before the first call into it. The boundary
 * (engine_boundary.S, generated by pc/tools/engine_boundary.py) gives:
 *  - rood_engine_slots: one per engine function the host calls; each of
 *    those names is a trampoline in the host jumping through its slot, so
 *    an address the host takes stays valid across reloads;
 *  - rood_engine_owned: the engine variables the host reads or writes,
 *    defined here (host-owned): the library's own references bind to them
 *    (the executable exports them), so they keep their values across reloads.
 * Reload (RPC reload): at the vsync boundary (pc_engine_vsync, called by
 * pc_tick after the RPC poll), with no engine frame on the stack, the
 * library saves what must outlive it into the carry store below and tears
 * its GPU state down (rood_engine_unload, engine_reload.c); it is unloaded;
 * the file is loaded again (a hard link of it, so the build replacing it
 * cannot change what is loaded, and the previous one stays loadable as the
 * fallback); slots are bound again; host-owned variables keep their values
 * (constants and addresses into the old library are refreshed); the new
 * library starts (rood_engine_resume) and answers the RPC (pc_rpc_reloaded).
 * Linux 64 bits only. */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <elf.h>
#include <errno.h>
#include <fcntl.h>
#include <link.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include <unwind.h>

extern void* rood_engine_slots[];
extern const char* const rood_engine_slot_names[];
extern const int rood_engine_slot_count;
struct rood_owned {
    const char* name;
    unsigned char* host;
    uint64_t size, constant;
};
extern const struct rood_owned rood_engine_owned[];
extern const int rood_engine_owned_count;
extern void rood_engine_unbound(void);

/* The base the library is linked at (build_boot.py): above the game stack
 * (0x60000000..0x64000000), below guest RAM. */
#define ENGINE_BASE 0x64000000u
#define GAME_BASE 0x18000000u /* the game's pinned code and state (snapshot_layout.py) */

static void* handle;
static char library[1024]; /* the library the build writes */
static char live[1100];    /* the hard link of it that is loaded */
static unsigned generation;
static uintptr_t mapped_start, mapped_end; /* the loaded library's address range */
static uintptr_t mapped_bias; /* its load bias: 0 at the base it is linked at */
static int callback_text(struct dl_phdr_info* info, size_t size, void* data);
void* pc_engine_carry_take(const char* name, size_t* size);

__attribute__((noreturn)) void rood_engine_missing(int index)
{
    fprintf(stderr, "[engine] %s called with no engine library loaded\n",
        index >= 0 && index < rood_engine_slot_count ? rood_engine_slot_names[index] : "?");
    abort();
}

static int callback_range(struct dl_phdr_info* info, size_t size, void* data)
{
    (void)size;
    const char* name = data;
    if (!info->dlpi_name || strcmp(info->dlpi_name, name))
        return 0;
    uintptr_t lo = UINTPTR_MAX, hi = 0;
    for (int i = 0; i < info->dlpi_phnum; i++)
        if (info->dlpi_phdr[i].p_type == PT_LOAD) {
            uintptr_t start = info->dlpi_addr + info->dlpi_phdr[i].p_vaddr;
            lo = start < lo ? start : lo;
            hi = start + info->dlpi_phdr[i].p_memsz > hi ? start + info->dlpi_phdr[i].p_memsz : hi;
        }
    mapped_start = lo, mapped_end = hi, mapped_bias = info->dlpi_addr;
    return 1;
}

/* The library file: ROOD_ENGINE_LIBRARY, else librood_engine.so beside the executable. */
static void library_path(void)
{
    const char* env = getenv("ROOD_ENGINE_LIBRARY");
    if (env && *env) {
        snprintf(library, sizeof library, "%s", env);
        return;
    }
    char exe[900];
    ssize_t n = readlink("/proc/self/exe", exe, sizeof exe - 1);
    exe[n > 0 ? n : 0] = 0;
    char* slash = strrchr(exe, '/');
    if (slash)
        slash[1] = 0;
    snprintf(library, sizeof library, "%slibrood_engine.so", slash ? exe : "./");
}

/* Load the library (a hard link of `path`: a build replacing the file
 * meanwhile does not change what is loaded), resolve every slot. NULL and
 * the reason when it cannot be used; nothing of it stays loaded then. */
static void* open_library(const char* path, char* why, int size)
{
    char link_path[1100];
    snprintf(link_path, sizeof link_path, "%s.live-%d-%u", path, (int)getpid(), generation + 1);
    unlink(link_path);
    if (link(path, link_path)) {
        snprintf(why, (size_t)size, "cannot link %s: %s", path, strerror(errno));
        return NULL;
    }
    void* h = dlopen(link_path, RTLD_NOW | RTLD_LOCAL);
    if (!h) {
        snprintf(why, (size_t)size, "%s", dlerror());
        unlink(link_path);
        return NULL;
    }
    int missing = 0;
    int (*abi)(void) = (int (*)(void))dlsym(h, "rood_engine_abi");
    if (!abi || abi() != 1)
        missing++, snprintf(why, (size_t)size, "the library's reload interface differs (rood_engine_abi)");
    for (int i = 0; i < rood_engine_slot_count && !missing; i++)
        if (!dlsym(h, rood_engine_slot_names[i])) {
            if (!missing++)
                snprintf(why, (size_t)size, "the library has no %s", rood_engine_slot_names[i]);
        }
    for (int i = 0; i < rood_engine_owned_count && !missing; i++) {
        const struct rood_owned* o = &rood_engine_owned[i];
        void* own = dlsym(h, o->name);
        Dl_info info;
        const ElfW(Sym)* symbol = NULL;
        if (!own)
            missing++, snprintf(why, (size_t)size, "the library has no variable %s", o->name);
        else if (dladdr1(own, &info, (void**)&symbol, RTLD_DL_SYMENT) && symbol && symbol->st_size != o->size)
            missing++, snprintf(why, (size_t)size, "%s changed size (%llu bytes, the host has %llu): rebuild the host "
                "(build_boot.py --engine-library) and restart", o->name, (unsigned long long)symbol->st_size,
                (unsigned long long)o->size);
        /* The executable must export it, or the library would use its own copy. */
        else if (dlsym(RTLD_DEFAULT, o->name) != o->host)
            missing++, snprintf(why, (size_t)size, "the host does not export %s", o->name);
    }
    if (missing) {
        dlclose(h);
        unlink(link_path);
        return NULL;
    }
    snprintf(live, sizeof live, "%s", link_path);
    return h;
}

static void bind_slots(void* h)
{
    for (int i = 0; i < rood_engine_slot_count; i++)
        rood_engine_slots[i] = dlsym(h, rood_engine_slot_names[i]);
}

static int all_zero(const unsigned char* p, uint64_t size)
{
    for (uint64_t i = 0; i < size; i++)
        if (p[i])
            return 0;
    return 1;
}

static void remove_live(void)
{
    if (live[0])
        unlink(live);
}

static void pc_game_start(void);
static void pc_game_vsync(void);

/* main (boot_runtime.c), before the first call into the engine. */
void pc_engine_start(void)
{
    library_path();
    char why[512] = "";
    handle = open_library(library, why, (int)sizeof why);
    if (!handle) {
        fprintf(stderr, "[engine] cannot load %s: %s\n", library, why);
        exit(1);
    }
    ++generation;
    pc_game_start();
    atexit(remove_live);
    bind_slots(handle);
    /* Host-owned variables start with the library's initial values (a
     * library constructor that already set one through the host wins). */
    for (int i = 0; i < rood_engine_owned_count; i++) {
        const struct rood_owned* o = &rood_engine_owned[i];
        if (all_zero(o->host, o->size))
            memcpy(o->host, dlsym(handle, o->name), (size_t)o->size);
    }
    dl_iterate_phdr(callback_range, live);
    dl_iterate_phdr(callback_text, live);
    fprintf(stderr, "[engine] loaded %s at %#lx (%d functions, %d host-owned variables)\n", library,
        (unsigned long)mapped_start, rood_engine_slot_count, rood_engine_owned_count);
    if (mapped_start != ENGINE_BASE)
        fprintf(stderr, "[engine] warning: not at its base %#x (taken): engine addresses may not fit a guest "
                        "pointer\n", ENGINE_BASE);
}

/* ---- the carry store: named blobs that outlive the library ---- */
struct carry {
    struct carry* next;
    char name[32];
    size_t size;
    unsigned char data[];
};
static struct carry* carried;
int pc_engine_carry_put(const char* name, const void* data, size_t size)
{
    void* old = pc_engine_carry_take(name, &(size_t) { 0 });
    free(old);
    struct carry* c = malloc(sizeof *c + size);
    if (!c)
        return 0;
    snprintf(c->name, sizeof c->name, "%s", name);
    c->size = size;
    memcpy(c->data, data, size);
    c->next = carried;
    carried = c;
    return 1;
}
/* The blob put under `name` (malloc'd: the caller frees it) and its size;
 * NULL when there is none. It leaves the store. */
void* pc_engine_carry_take(const char* name, size_t* size)
{
    for (struct carry** at = &carried; *at; at = &(*at)->next) {
        struct carry* c = *at;
        if (strcmp(c->name, name))
            continue;
        *at = c->next;
        void* data = malloc(c->size ? c->size : 1);
        if (data)
            memcpy(data, c->data, c->size);
        *size = c->size;
        free(c);
        return data;
    }
    *size = 0;
    return NULL;
}
static void carry_clear(void)
{
    while (carried) {
        struct carry* next = carried->next;
        free(carried);
        carried = next;
    }
}

/* ---- reload ---- */
extern int rood_engine_unload(char* why, int size); /* engine_reload.c, through its slot */
extern void rood_engine_resume(void);
extern void pc_rpc_reloaded(void); /* dev_rpc.c */
extern unsigned pc_vsync_count(void);
static int reload_requested;
static char status[1024];
static int status_ok;

int pc_engine_reload_request(void)
{
    reload_requested = 1;
    return 1;
}
int pc_engine_reload_wanted(void) { return reload_requested; }
/* RPC reload's reply: the result object, or the error (0). */
int pc_engine_reload_status(char* out, int size)
{
    snprintf(out, (size_t)size, "%s", status);
    return status_ok;
}

static uintptr_t text_start, text_end; /* the loaded library's code */
static int callback_text(struct dl_phdr_info* info, size_t size, void* data)
{
    (void)size;
    if (!info->dlpi_name || strcmp(info->dlpi_name, (const char*)data))
        return 0;
    for (int i = 0; i < info->dlpi_phnum; i++)
        if (info->dlpi_phdr[i].p_type == PT_LOAD && (info->dlpi_phdr[i].p_flags & PF_X)) {
            text_start = info->dlpi_addr + info->dlpi_phdr[i].p_vaddr;
            text_end = text_start + info->dlpi_phdr[i].p_memsz;
        }
    return 1;
}
/* Whether a frame of the library is live on this thread's stack: the game
 * called into the engine, and the engine into the game, which now waits for
 * this vsync; reloading now would return into unmapped code. The unwinder
 * walks the real frames (the game's units have unwind tables): a word that
 * only looks like a return address in a frame's padding does not count. */
extern void vs_main_exec(void); /* main.c: the game thread starts here (boot_runtime.c run_game) */
struct frames {
    int engine, count;
    uintptr_t at;
};
static _Unwind_Reason_Code frame(struct _Unwind_Context* context, void* data)
{
    struct frames* f = data;
    uintptr_t ip = _Unwind_GetIP(context);
    if (ip >= text_start && ip < text_end && !f->engine++)
        f->at = ip;
    /* The game thread's first frame: what lies below it was made by the
     * process that saved a resumed snapshot (its libc's addresses), which
     * the unwinder must not try to read. */
    if (_Unwind_GetRegionStart(context) == (uintptr_t)vs_main_exec)
        return _URC_END_OF_STACK;
    return ++f->count < 4096 ? _URC_NO_REASON : _URC_END_OF_STACK;
}
static int engine_frame_on_stack(void)
{
    struct frames f = { 0, 0, 0 };
    _Unwind_Backtrace(frame, &f);
    if (f.engine) {
        Dl_info where;
        fprintf(stderr, "[engine] a frame of the library is live: %#lx (%s)\n", (unsigned long)f.at,
            dladdr((void*)f.at, &where) && where.dli_sname ? where.dli_sname : "?");
    }
    return f.engine;
}

/* ---- addresses into the library kept by the host ----
 * Before the old library is unloaded, the host's own writable data is
 * scanned for 8-byte words that address it. Raw bytes read as such a word
 * too (a card path ending ".mcd\0\0\0\0" is 0x64636d2e), so a word counts
 * only when it is what a pointer would be: the entry of a function or an
 * address inside a data object of the library, by its symbol table (the
 * file's .symtab: static functions included). Each is reported with the host
 * variable holding it and what it points at (the reply's stale_host). */
struct elf_symbols {
    const ElfW(Sym)* symbols;
    size_t count;
    const char* names;
    const ElfW(Shdr)* sections;
    size_t section_count;
    void* map;
    size_t size;
};
static int elf_symbols_open(const char* path, struct elf_symbols* e)
{
    memset(e, 0, sizeof *e);
    int fd = open(path, O_RDONLY | O_CLOEXEC);
    struct stat st;
    if (fd < 0 || fstat(fd, &st) || st.st_size < (off_t)sizeof(ElfW(Ehdr))) {
        if (fd >= 0)
            close(fd);
        return 0;
    }
    void* map = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    if (map == MAP_FAILED)
        return 0;
    const unsigned char* base = map;
    const ElfW(Ehdr)* eh = map;
    e->map = map, e->size = (size_t)st.st_size;
    if (memcmp(eh->e_ident, ELFMAG, SELFMAG) || eh->e_shoff + (size_t)eh->e_shnum * sizeof(ElfW(Shdr)) > e->size)
        return 1;
    const ElfW(Shdr)* sh = (const ElfW(Shdr)*)(base + eh->e_shoff);
    e->sections = sh, e->section_count = eh->e_shnum;
    for (int i = 0; i < eh->e_shnum; i++)
        if (sh[i].sh_type == SHT_SYMTAB && sh[i].sh_link < eh->e_shnum
            && sh[i].sh_offset + sh[i].sh_size <= e->size && sh[sh[i].sh_link].sh_offset < e->size) {
            e->symbols = (const ElfW(Sym)*)(base + sh[i].sh_offset);
            e->count = sh[i].sh_size / sizeof(ElfW(Sym));
            e->names = (const char*)(base + sh[sh[i].sh_link].sh_offset);
        }
    return 1;
}
static void elf_symbols_close(struct elf_symbols* e)
{
    if (e->map)
        munmap(e->map, e->size);
    memset(e, 0, sizeof *e);
}
/* The symbol `address` (minus `bias`) is the entry of (a function), the
 * start of (an object) or lies inside (a writable object: read-only blobs
 * such as the embedded shaders hold no state a pointer would follow, and raw
 * bytes land inside them); with any = 1, the nearest symbol below it of
 * either kind. */
static const ElfW(Sym)* elf_symbol_at(const struct elf_symbols* e, uintptr_t address, uintptr_t bias, int any)
{
    const ElfW(Sym)* best = NULL;
    for (size_t i = 0; i < e->count; i++) {
        const ElfW(Sym)* s = &e->symbols[i];
        int type = ELF64_ST_TYPE(s->st_info);
        uintptr_t at = s->st_value + bias;
        if (!s->st_name || s->st_shndx == SHN_UNDEF || (type != STT_FUNC && type != STT_OBJECT))
            continue;
        if (any) {
            if (at <= address && (!best || s->st_value > best->st_value))
                best = s;
        } else if (type == STT_FUNC || address == at) {
            if (address == at)
                return s;
        } else if (address > at && address < at + s->st_size && s->st_shndx < e->section_count
                   && (e->sections[s->st_shndx].sh_flags & SHF_WRITE))
            return s;
    }
    return best;
}
struct scan {
    uintptr_t lo, hi, bias;
    struct elf_symbols library, host;
    int found, candidates;
    char report[700];
    size_t used;
};
static int callback_scan(struct dl_phdr_info* info, size_t size, void* data)
{
    (void)size;
    struct scan* scan = data;
    if (info->dlpi_name && info->dlpi_name[0])
        return 0; /* the executable only */
    for (int i = 0; i < info->dlpi_phnum; i++) {
        const ElfW(Phdr)* ph = &info->dlpi_phdr[i];
        /* The host's own data, not the game's pinned state (from 0x18000000:
         * its pointers are 4-byte guest addresses). */
        if (ph->p_type != PT_LOAD || !(ph->p_flags & PF_W) || info->dlpi_addr + ph->p_vaddr >= GAME_BASE)
            continue;
        const uintptr_t* p = (const uintptr_t*)((info->dlpi_addr + ph->p_vaddr + 7) & ~(uintptr_t)7);
        const uintptr_t* end = (const uintptr_t*)(info->dlpi_addr + ph->p_vaddr + ph->p_memsz);
        for (; p + 1 <= end; p++) {
            if (*p < scan->lo || *p >= scan->hi || p == &text_start || p == &text_end || p == &mapped_start
                || p == &mapped_end || p == &mapped_bias || ((const char*)p >= (const char*)scan
                    && (const char*)p < (const char*)(scan + 1)))
                continue;
            if (p >= (const uintptr_t*)rood_engine_slots && p < (const uintptr_t*)(rood_engine_slots + rood_engine_slot_count))
                continue;
            if (++scan->candidates > 4096)
                return 1; /* raw data, not pointers: enough */
            const ElfW(Sym)* target = elf_symbol_at(&scan->library, *p, scan->bias, 0);
            const ElfW(Sym)* holder = elf_symbol_at(&scan->host, (uintptr_t)p, 0, 1);
            const char* host_name = holder ? scan->host.names + holder->st_name : "?";
            unsigned long offset = holder ? (unsigned long)((uintptr_t)p - holder->st_value) : 0ul;
            if (!target) {
                if (scan->candidates <= 4)
                    fprintf(stderr, "[engine] host data %s+%#lx holds %#lx: no function or object there (not a "
                                    "pointer)\n", host_name, offset, (unsigned long)*p);
                continue;
            }
            const char* name = scan->library.names + target->st_name;
            unsigned long into = (unsigned long)(*p - scan->bias - target->st_value);
            fprintf(stderr, "[engine] host data %s+%#lx (%p) holds %#lx, %s+%#lx in the old library\n", host_name,
                offset, (const void*)p, (unsigned long)*p, name, into);
            if (scan->found++ < 8 && scan->used + 200 < sizeof scan->report)
                scan->used += (size_t)snprintf(scan->report + scan->used, sizeof scan->report - scan->used,
                    "%s\"%s+%#lx -> %s+%#lx\"", scan->found > 1 ? "," : "", host_name, offset, name, into);
        }
    }
    return 1;
}

static double now_ms(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec * 1e3 + t.tv_nsec / 1e6;
}

/* Host-owned variables after a reload: constants from the new library;
 * words holding an address in the old library from the new library's
 * initial value; a size that changed refuses the library (checked by
 * open_library through the symbol sizes). */
static void refresh_owned(uintptr_t old_lo, uintptr_t old_hi)
{
    for (int i = 0; i < rood_engine_owned_count; i++) {
        const struct rood_owned* o = &rood_engine_owned[i];
        const unsigned char* fresh = dlsym(handle, o->name);
        if (o->constant) {
            memcpy(o->host, fresh, (size_t)o->size);
            continue;
        }
        for (uint64_t at = 0; at + 8 <= o->size; at += 8) {
            uintptr_t word;
            memcpy(&word, o->host + at, 8);
            if (word >= old_lo && word < old_hi) {
                memcpy(o->host + at, fresh + at, 8);
                fprintf(stderr, "[engine] %s+%llu held an address in the old library: reset from the new one\n",
                    o->name, (unsigned long long)at);
            }
        }
    }
}

static void reload(void)
{
    double start = now_ms();
    char why[512] = "";
    status_ok = 0;
    if (rood_engine_unload(why, (int)sizeof why)) {
        snprintf(status, sizeof status, "reload refused (%s)", why);
        fprintf(stderr, "[engine] reload refused: %s\n", why);
        return;
    }
    uintptr_t old_lo = mapped_start, old_hi = mapped_end;
    char previous[sizeof live];
    snprintf(previous, sizeof previous, "%s", live);
    /* What the host still holds of this library, while its symbols can be read. */
    static struct scan scan;
    memset(&scan, 0, sizeof scan);
    scan.lo = old_lo, scan.hi = old_hi, scan.bias = mapped_bias;
    elf_symbols_open(previous, &scan.library);
    elf_symbols_open("/proc/self/exe", &scan.host);
    dl_iterate_phdr(callback_scan, &scan);
    elf_symbols_close(&scan.library);
    elf_symbols_close(&scan.host);
    dlclose(handle);
    handle = NULL;
    void* still = dlopen(previous, RTLD_NOW | RTLD_NOLOAD);
    if (still) {
        /* Something keeps it (a unique C++ symbol, a thread-local destructor): a
         * fresh copy would load elsewhere, above 4 GB. */
        dlclose(still);
        fprintf(stderr, "[engine] warning: the old library stays mapped (glibc did not unload it)\n");
    }
    for (int i = 0; i < rood_engine_slot_count; i++)
        rood_engine_slots[i] = (void*)rood_engine_unbound;
    double unloaded = now_ms();
    handle = open_library(library, why, (int)sizeof why);
    int fallback = !handle;
    if (fallback) {
        /* The previous library again (its hard link): the game goes on. */
        fprintf(stderr, "[engine] cannot load %s: %s; loading the previous one again\n", library, why);
        char error[512];
        handle = open_library(previous, error, (int)sizeof error);
        if (!handle) {
            fprintf(stderr, "[engine] the previous library does not load either: %s\n", error);
            abort();
        }
    }
    if (strcmp(previous, live))
        unlink(previous);
    ++generation;
    bind_slots(handle);
    dl_iterate_phdr(callback_range, live);
    dl_iterate_phdr(callback_text, live);
    refresh_owned(old_lo, old_hi);
    if (mapped_start != ENGINE_BASE)
        fprintf(stderr, "[engine] warning: loaded at %#lx, not at its base %#x\n", (unsigned long)mapped_start,
            ENGINE_BASE);
    double loaded = now_ms();
    rood_engine_resume();
    carry_clear(); /* what the new library did not take */
    double resumed = now_ms();
    if (fallback)
        snprintf(status, sizeof status, "the new library did not load (%s); the previous one runs again", why);
    else
        snprintf(status, sizeof status,
            "{\"reloaded\":true,\"generation\":%u,\"vsync\":%u,\"ms\":%.1f,\"unload_ms\":%.1f,\"load_ms\":%.1f,"
            "\"resume_ms\":%.1f,\"stale_host_words\":%d,\"stale_host\":[%s],\"address_like_words\":%d,\"base\":\"%#lx\"}",
            generation, pc_vsync_count(), resumed - start, unloaded - start, loaded - unloaded, resumed - loaded,
            scan.found, scan.report, scan.candidates, (unsigned long)mapped_start);
    if (!fallback) {
        /* The new library's note (rood_engine_note), letters, digits, '-' and '_' only. */
        const char* (*note)(void) = (const char* (*)(void))dlsym(handle, "rood_engine_note");
        const char* text = note ? note() : "";
        size_t at = strlen(status) - 1, n = 0;
        char clean[64];
        for (; text[n] && n < sizeof clean - 1; n++)
            clean[n] = (text[n] >= 'a' && text[n] <= 'z') || (text[n] >= 'A' && text[n] <= 'Z')
                    || (text[n] >= '0' && text[n] <= '9') || text[n] == '-' ? text[n] : '_';
        clean[n] = 0;
        snprintf(status + at, sizeof status - at, ",\"note\":\"%s\"}", clean);
    }
    status_ok = !fallback;
    fprintf(stderr, "[engine] %s generation %u at vsync %u in %.0f ms (unload %.0f, load %.0f, start %.0f)%s\n",
        fallback ? "previous library reloaded:" : "reloaded", generation, pc_vsync_count(), resumed - start,
        unloaded - start, loaded - unloaded, resumed - loaded,
        scan.found ? "; host data still pointed into the old library (above)" : "");
}

/* pc_tick (boot_runtime.c), after the RPC poll: a requested reload. A
 * refused one is answered at once (the caller retries: dev_loop.sh): waiting
 * here would run frames of a paused game. */
void pc_engine_vsync(void)
{
    pc_game_vsync();
    while (reload_requested) {
        reload_requested = 0;
        if (engine_frame_on_stack()) {
            status_ok = 0;
            snprintf(status, sizeof status, "reload refused (retry: an engine call is on the game stack)");
        } else
            reload();
        pc_rpc_reloaded(); /* the reply, then the rest of the poll (it may ask again) */
        pc_game_vsync();
    }
}

